import random, struct

def fields(x):
    (bits,) = struct.unpack(">Q", struct.pack(">d", x))
    return bits >> 63, (bits >> 52) & 0x7FF, bits & ((1 << 52) - 1)

assert float_from_fields(0, 1023, 0) == 1.0
assert float_from_fields(1, 1024, 1 << 50) == -2.5
assert float_from_fields(*fields(0.1)) == 0.1
rng = random.Random(4)
for _ in range(2000):
    x = rng.uniform(-1e6, 1e6) * 10.0 ** rng.randint(-200, 200)
    if x != 0.0:
        assert float_from_fields(*fields(x)) == x, x
print("All tests passed!")

exercises.solution:
```python
def count_code_points(data):
    return sum(1 for b in data if (b & 0xC0) != 0x80)
```

Every code point's encoding contains exactly one lead byte (`0xxxxxxx`, `110xxxxx`, `1110xxxx` or `11110xxx`) followed by zero to three continuation bytes (`10xxxxxx`). So the number of code points equals the number of non-continuation bytes. The mask `0xC0` (`1100 0000`) keeps the top two bits, and a continuation byte has them equal to `10`, giving `0x80`. The same property lets a program that lands at an arbitrary byte offset skip forward to the next lead byte and resynchronise, something that legacy multi-byte encodings could not do.
